  permg_pct=permg_rate*100;
  ty_pct=ty_rate*100;

  print alpha, naive_pct, diff_pct, thresh_pct, permg_pct, ty_pct;
}' /home/ubuntu/.agent-ml-research-idea_gen_0514_4/projects/distrib_canary_collapse/artifacts/dose_response_d120_recompiled.csv | 
awk '{
  alpha=$1;
  naive[alpha]+=$2; diff[alpha]+=$3; thresh[alpha]+=$4; permg[alpha]+=$5; ty[alpha]+=$6;
  count[alpha]++;
}
